// Given: the demo loop. Do not edit this file.
//
// Physics runs at a fixed timestep; rendering runs at the screen's rate.
// The accumulator collects real time and spends it in whole steps of dt
// (pill 1.5 explains why). Pause, single step and slow motion are built in.

export type LoopOptions = {
  /** Advance the simulation by dt seconds. */
  step: (dt: number) => void;
  /** Draw the current state. Called once per animation frame. */
  render: () => void;
  /** Fixed timestep in seconds. Default 1/60. */
  dt?: number;
};

export type Loop = {
  readonly paused: boolean;
  /** Simulation speed: 1 is real time, 0.25 is slow motion. */
  timeScale: number;
  pause(): void;
  resume(): void;
  toggle(): void;
  /** Advance exactly one step (use while paused). */
  stepOnce(): void;
  stop(): void;
};

// Avoids a "spiral of death" after the tab was in the background:
// at most this much real time is simulated per animation frame.
const MAX_FRAME_TIME = 0.25;

export function startLoop(options: LoopOptions): Loop {
  const dt = options.dt ?? 1 / 60;
  let accumulator = 0;
  let last = performance.now();
  let paused = false;
  let running = true;
  let handle = 0;

  const frame = (now: number) => {
    if (!running) return;
    const elapsed = Math.min((now - last) / 1000, MAX_FRAME_TIME);
    last = now;
    if (!paused) {
      accumulator += elapsed * loop.timeScale;
      while (accumulator >= dt) {
        options.step(dt);
        accumulator -= dt;
      }
    }
    options.render();
    handle = requestAnimationFrame(frame);
  };

  const loop: Loop = {
    get paused() {
      return paused;
    },
    timeScale: 1,
    pause: () => {
      paused = true;
    },
    resume: () => {
      paused = false;
      accumulator = 0;
      last = performance.now();
    },
    toggle: () => (paused ? loop.resume() : loop.pause()),
    stepOnce: () => {
      options.step(dt);
      options.render();
    },
    stop: () => {
      running = false;
      cancelAnimationFrame(handle);
    },
  };

  handle = requestAnimationFrame(frame);
  return loop;
}
